function rec(id){if(id==='home'||id==='menu')return;NAV.rc=[id].concat(NAV.rc.filter(x=>x!==id)).slice(0,5);try{localStorage.setItem('nav397:rc',JSON.stringify(NAV.rc))}catch(e){}}
