const OVL=[['es','quote'],['aptdb','aptdb'],['ap','area'],['hq','hq'],['hqd','hqd']];
function ovs(){return OVL.filter(([id])=>document.getElementById(id)).map(x=>x[1])}
function baseLive(){const v=document.getElementById('vmenu');if(v&&!v.hidden)return'menu';const pg=+document.body.dataset.pg;if(pg===8)return(window.FM&&FM.tab==='mesh')?'mesh':'fill';return({0:'calc',1:'db',2:'home',3:(window.SYM=='db'?'spdb':'sys'),4:'tds',5:'csv',7:'adm',9:'lcc',10:'cmp'})[pg]||'home'}
function owned(){const o=OVL.find(x=>x[1]===NAV.cur);return o?o[0]:null}
function stray(){const own=owned();return OVL.filter(([id])=>id!==own&&document.getElementById(id)).map(x=>x[0])}
function here(it){if(it.sheet||!it.page)return false;const pid=it.page;if(pid!==NAV.cur)return false;const o=OVL.find(x=>x[1]===pid);if(o)return!!document.getElementById(o[0])&&!stray().length;return baseLive()===pid&&!ovs().length}
function sync(){if(NAV.going)return;const o=OVL.find(x=>x[1]===NAV.cur);
 if(o&&!document.getElementById(o[0])){const b=baseLive();if(NAV.stack[NAV.stack.length-1]===b)NAV.stack.pop();NAV.cur=b}
 refresh()}
function push(c){if(c&&NAV.stack[NAV.stack.length-1]!==c){NAV.stack.push(c);NAV.stack=NAV.stack.slice(-30)}}
function go(id,back){const it=IT[id];if(!it)return;const pid=it.page;
 if(!back&&here(it)){subClose();try{window.scrollTo(0,0)}catch(e){}refresh();return}
 if(it.sheet){subClose();document.querySelectorAll('.pqs').forEach(e=>e.remove());rec(id);try{it.o()}catch(e){console.error(e)}return}closeAll();rec(id);
 if(pid&&!back&&NAV.cur!==pid)push(NAV.cur);
 NAV.going=1;try{if(it.ov)T(2);it.o()}catch(e){console.error(e)}finally{NAV.going=0}
 if(pid)NAV.cur=pid;refresh()}
function closeStray(){const s=stray();if(!s.length)return false;s.forEach(id=>{const e=document.getElementById(id);if(!e)return;if(id==='aptdb'){try{aptDbClose();if(document.getElementById('aptdb'))e.remove()}catch(x){e.remove()}}else e.remove()});document.body.classList.remove('pdlock');document.documentElement.classList.remove('pdlock');refresh();return true}
function navBack(){sync();if(closeStray())return;try{if(window.hqBack&&window.hqBack())return}catch(e){}
 let p;while((p=NAV.stack.pop())&&(p===NAV.cur||!IT[p]));
 if(p)go(p,true);else if(NAV.cur!=='home'||ovs().length||baseLive()!=='home')go('home',true)}
function navHome(){closeAll();NAV.going=1;try{T(2)}catch(e){console.error(e)}finally{NAV.going=0}if(NAV.cur!=='home')push(NAV.cur);NAV.cur='home';refresh()}
window.navGo=go;window.navBack=navBack;window.navHome=navHome;
function refresh(){const cat=CAT[NAV.cur]||'',ox=ovs().length>0,atHome=NAV.cur==='home'&&!ox&&baseLive()==='home';document.querySelectorAll('#gnav .hni').forEach(b=>b.classList.toggle('on',b.dataset.cat===cat));
 const g=$('#gnav');if(g){const b=g.querySelector('[data-a=back]'),h=g.querySelector('[data-a=home]'),m=g.querySelector('[data-a=menu]');if(b)b.disabled=atHome&&!NAV.stack.length;if(h)h.disabled=atHome;if(m)m.classList.toggle('on',NAV.cur==='menu')}
 document.body.classList.toggle('inapp',!atHome)}
