function menuBody(q){const S=items();
 if(q){const n=norm(q),r=[];S.forEach(s=>s.it.forEach(id=>{const it=IT[id];if(norm(it.n).includes(n)||norm(it.k).includes(n)||norm(s.t).includes(n))r.push([id,s])}));
  return r.length?`<div class="mres">${r.map(([id,s])=>`<button type="button" class="mt" data-go="${id}" style="--c:${s.c};--cb:${s.cb}"><span class="mti">${svg(IC[id])}</span><span class="mtl">${IT[id].n}<small>${s.t}</small></span>${CV}</button>`).join('')}</div>`:`<div class="mnone">‘${esc2(q)}’에 해당하는 메뉴가 없습니다</div>`}
 const rc=NAV.rc.filter(i=>IT[i]);
 return S.map(s=>`<section class="msec" style="--c:${s.c};--c2:${s.c2};--cb:${s.cb};--bg:${s.bg};--bd:${s.bd};--art:url(${ART[s.art]})"><div class="msh"><span class="msi">${svg(IC[s.ic])}</span><div><b>${s.t}</b><small>${s.d}</small></div></div><div class="mgrid" style="grid-template-columns:repeat(${Math.min(s.it.length,5)},minmax(0,1fr))">${s.it.map(id=>tile(id,s,s.it.length>=5)).join('')}</div></section>`).join('')
 +`<section class="mrc"><div class="mrh"><span class="msi">${svg(IC.rc)}</span><div><b>최근 사용 메뉴</b><small>최근에 사용한 메뉴를 빠르게 이동할 수 있습니다.</small></div><button type="button" data-go="home">전체 내역 보기 ›</button></div>${rc.length?`<div class="mrr">${rc.map(id=>tile(id,secOf(id))).join('')}</div>`:'<div class="mrn">아직 사용한 메뉴가 없습니다.</div>'}</section>`}
const esc2=s=>String(s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const norm=s=>String(s||'').toLowerCase().replace(/[\s·()\-_.]/g,'');
function search(q){const n=norm(q);if(!n)return[];const r=[];items().forEach(s=>s.it.forEach(id=>{const it=IT[id];if(norm(it.n).includes(n)||norm(it.k).includes(n))r.push(id)}));return r}
function exact(q){const n=norm(q);if(n.length<2)return null;return Object.keys(IT).find(id=>id!=='home'&&id!=='menu'&&(norm(IT[id].n)===n||IT[id].k.split(' ').some(w=>norm(w)===n)))||null}
